"use client";

import React, { useRef, useCallback } from "react";

const METAL_CLICK_DATA_URI =
  "data:audio/mpeg;base64,";

export function CadIsometricCover() {
  const audioRef = useRef<HTMLAudioElement | null>(null);

  const playClickSound = useCallback(() => {
    try {
      if (!audioRef.current) {
        audioRef.current = new Audio(METAL_CLICK_DATA_URI);
        audioRef.current.volume = 0.5;
      }
      audioRef.current.currentTime = 0;
      audioRef.current.play().catch(() => {});
    } catch {}
  }, []);

  return (
    <div
      onClick={playClickSound}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          playClickSound();
        }
      }}
      className="relative w-full h-full min-h-[140px] sm:min-h-[160px] md:min-h-[180px] flex items-center justify-center cursor-pointer select-none overflow-hidden group transition-colors"
      title="KAL — Click for sound"
      aria-label="KAL"
    >
      {/* Typed KAL in pure Tiny5 font */}
      <span className="font-tiny5 text-6xl sm:text-7xl md:text-8xl lg:text-9xl tracking-[0.25em] pl-[0.25em] text-zinc-950 dark:text-zinc-50 transition-transform duration-150 active:scale-95 group-hover:opacity-90">
        KAL
      </span>
    </div>
  );
}
